<?php
class AdminNtCreatorRewardsPublishersController extends ModuleAdminController
{
    public function __construct(){parent::__construct();$this->bootstrap=true;}
    public function postProcess(){if(Tools::isSubmit('verifyPublisher')){$id=(int)Tools::getValue('id_publisher');$p=Db::getInstance()->getRow('SELECT * FROM `'._DB_PREFIX_.'ntcr_publisher` WHERE id_publisher='.$id.' AND id_shop='.(int)$this->context->shop->id);if(!$p||!$p['pending_handle'])$this->errors[]='Doğrulanacak kayıt bulunamadı.';else{$creator=trim((string)Tools::getValue('creator_id'));Db::getInstance()->update('ntcr_publisher',array('handle'=>pSQL($p['pending_handle']),'pending_handle'=>null,'creator_id'=>$creator===''?null:pSQL($creator),'status'=>'verified','date_upd'=>date('Y-m-d H:i:s')),'id_publisher='.$id);$this->confirmations[]='Yayıncı eşleştirmesi doğrulandı.';}}parent::postProcess();}
    public function initContent(){parent::initContent();$rows=Db::getInstance()->executeS('SELECT p.*,c.firstname,c.lastname,c.email FROM `'._DB_PREFIX_.'ntcr_publisher` p LEFT JOIN `'._DB_PREFIX_.'customer` c ON c.id_customer=p.id_customer WHERE p.id_shop='.(int)$this->context->shop->id.' ORDER BY p.id_publisher DESC');$this->context->smarty->assign('ntcr_publishers',$rows);$this->content=$this->context->smarty->fetch(_PS_MODULE_DIR_.'ntcreatorrewards/views/templates/admin/publishers.tpl');$this->context->smarty->assign('content',$this->content);}
}
